SELECT count(*) AS nrow,coalesce(sum(a IS NOT b),0) AS bad_endpoints,min(length(c0)),max(length(c0)),min(length(c1)),max(length(c1)),min(length(c2)),max(length(c2)),min(length(c3)),max(length(c3)),min(length(c4)),max(length(c4)),min(length(c5)),max(length(c5)),min(length(c6)),max(length(c6)),coalesce(sum(typeof(c0)<>'blob' OR typeof(c1)<>'blob' OR typeof(c2)<>'blob' OR typeof(c3)<>'blob' OR typeof(c4)<>'blob' OR typeof(c5)<>'blob' OR typeof(c6)<>'blob'),0) AS bad_types FROM t1;